// Primitive CSS: renders the kit's `src/theme/tokens/primitives/*.css` (and their barrel) from primitives.tokens.json
// and primitives.config.json, and the pieces the app artifact is assembled from.

import assert from 'node:assert/strict';
import { readFileSync } from 'node:fs';
import { resolve } from 'node:path';
import { declaration } from './dtcg.mjs';

export const PRIMITIVES_DIR = 'src/theme/tokens/primitives';

const HEADER = `/*
 * GENERATED by scripts/tokens/generate.mjs from design-system/tokens/source/primitives.tokens.json and
 * primitives.config.json. Do not edit: change those files and run \`pnpm tokens:generate\`.
 */`;

const globToRegExp = (pattern) =>
    new RegExp(
        `^${pattern
            .split('.')
            .map((part) => (part === '*' ? '([^.]+)' : part.replace(/[-/\\^$+?()|[\]{}]/g, '\\$&')))
            .join('\\.')}$`,
    );

// token path -> CSS custom property, by the first matching `cssNames` rule.
export const createVarOf = (cssNames) => {
    const rules = Object.entries(cssNames).map(([pattern, template]) => [globToRegExp(pattern), template]);
    return (path) => {
        for (const [regexp, template] of rules) {
            const match = path.match(regexp);
            if (match != null) {
                return template.replace(/\$(\d)/g, (_, n) => match[Number(n)]);
            }
        }
        throw new Error(`No CSS name for token ${path} (primitives.config.json cssNames)`);
    };
};

const indent = (text) =>
    text
        .split('\n')
        .map((line) => (line === '' ? line : `    ${line}`))
        .join('\n');

// Direct children of a group, as token paths (a child must be a token).
const groupTokens = (tokens, group, match) => {
    const paths = [...tokens.keys()].filter(
        (path) => path.startsWith(`${group}.`) && !path.slice(group.length + 1).includes('.'),
    );
    const wanted = match == null ? paths : paths.filter((path) => new RegExp(match).test(path.slice(group.length + 1)));
    assert(wanted.length > 0, `primitives.config.json: no token under ${group}${match ? ` matching ${match}` : ''}`);
    return wanted;
};

// Returns the rendered files (body without header, by file name) and fails when a token is not placed exactly once.
export const renderPrimitives = ({ tokens, config, cssDir, flat = false }) => {
    const varOf = createVarOf(config.cssNames);
    const emitted = new Map();
    const emit = (path) => {
        assert(tokens.has(path), `primitives.config.json: unknown token ${path}`);
        assert(!emitted.has(path), `primitives.config.json: token ${path} is placed twice`);
        emitted.set(path, true);
        return declaration(varOf(path), tokens.get(path), varOf, flat);
    };
    const bodies = new Map();
    for (const [file, blocks] of Object.entries(config.files)) {
        const rendered = blocks.map((block) => {
            if (block.verbatim != null) {
                return readFileSync(resolve(cssDir, block.verbatim), 'utf8').trimEnd();
            }
            const lines = block.lines.flatMap((line) => {
                if (line.raw != null) {
                    return [line.raw];
                }
                if (line.comment != null) {
                    return [`/* ${line.comment} */`];
                }
                if (line.blank) {
                    return [''];
                }
                if (line.token != null) {
                    return [emit(line.token)];
                }
                if (line.tokens != null) {
                    return groupTokens(tokens, line.tokens, line.match).map(emit);
                }
                throw new Error(`primitives.config.json: unknown line ${JSON.stringify(line)} in ${file}`);
            });
            return `${block.at} {\n${indent(lines.join('\n'))}\n}`;
        });
        bodies.set(file, rendered.join('\n\n'));
    }
    const missing = [...tokens.keys()].filter((path) => !emitted.has(path));
    assert.equal(missing.length, 0, `primitives.config.json places no CSS for: ${missing.join(', ')}`);
    return { bodies, varOf };
};

// File name -> full generated text (header, body, trailing newline), plus the barrel.
export const primitiveFiles = (bodies) => {
    const files = new Map();
    for (const [file, body] of bodies) {
        files.set(`${PRIMITIVES_DIR}/${file}`, `${HEADER}\n\n${body}\n`);
    }
    const barrel = [...bodies.keys()].map((file) => `@import "./${file}";`).join('\n');
    files.set(`${PRIMITIVES_DIR}/index.css`, `${HEADER}\n\n${barrel}\n`);
    return files;
};
